140	            <label className="text-xs font-semibold text-[#71717A] dark:text-[#A1A1AA] mb-1 block">Telefone</label>
141	            <input value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="Ex: 11999998888"
142	              className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
143	          </div>
144	          <div>
145	            <label className="text-xs font-semibold text-[#71717A] dark:text-[#A1A1AA] mb-1 block">E-mail</label>
146	            <input type="email" value={email} onChange={(e) => setEmail(e.target.value)}
147	              className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
148	          </div>
149	          <div>
150	            <label className="text-xs font-semibold text-[#71717A] dark:text-[#A1A1AA] mb-1 block">
151	              {editando ? 'Nova senha (deixe em branco pra manter a atual)' : 'Senha de acesso'}
152	            </label>
153	            <input type="password" value={password} onChange={(e) => setPassword(e.target.value)}
154	              placeholder="Mínimo 8 caracteres" minLength={8} required={!editando}
155	              className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
156	            {!editando && (
157	              <p className="text-[11px] text-[#A1A1AA] mt-1">Compartilhe telefone/e-mail e essa senha com o motoboy — é o login dele no app.</p>
158	            )}
159	          </div>
160	        </div>
161	
162	        <div className="flex gap-2 mt-5">
163	          <button type="button" onClick={onFechar} className="flex-1 py-2.5 border rounded-xl text-sm text-gray-700 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-950/40">
164	            Cancelar
165	          </button>
166	          <button type="submit" disabled={processando}
167	            className="flex-1 py-2.5 bg-[#FF441F] text-white rounded-xl text-sm font-semibold hover:bg-[#E63A19] disabled:opacity-50">
168	            {processando ? 'Salvando...' : 'Salvar'}
169	          </button>
170	        </div>
171	      </form>
172	    </div>
173	  );
174	};
175	
176	const RestauranteMotoboys = () => {
177	  const [aba, setAba] = useState('pendentes'); // pendentes | aceitas | recusadas
178	  const [motoboys, setMotoboys] = useState([]);
179	  const [solicitacoes, setSolicitacoes] = useState([]);
180	  const [recusadas, setRecusadas] = useState([]);
181	  const [loading, setLoading] = useState(true);
182	  const [msg, setMsg] = useState(null);
183	  const [ficha, setFicha] = useState(null); // solicitacao selecionada
184	  const [fichaSomenteLeitura, setFichaSomenteLeitura] = useState(false);
185	  const [processando, setProcessando] = useState(false);
186	  const [removendo, setRemovendo] = useState(null);
187	  const [revisando, setRevisando] = useState(null);
188	  const [forcandoLogout, setForcandoLogout] = useState(null);
189	  const [formModal, setFormModal] = useState(null); // null | 'novo' | motoboy (edição)
190	  const [salvandoForm, setSalvandoForm] = useState(false);
191	  const [erroForm, setErroForm] = useState(null);
192	  const [excluindo, setExcluindo] = useState(null);
193	  const [bloqueando, setBloqueando] = useState(null);
194	
195	  const reload = useCallback(() => {
196	    setLoading(true);
197	    Promise.all([listarMotoboys(), listarSolicitacoesMotoboy('pendente'), listarSolicitacoesMotoboy('recusado')])
198	      .then(([mbs, sols, recs]) => {
199	        setMotoboys(mbs.motoboys ?? []);
200	        setSolicitacoes(sols.solicitacoes ?? []);
201	        setRecusadas(recs.solicitacoes ?? []);
202	      })
203	      .catch((e) => setMsg({ tipo: 'erro', texto: e.message }))
204	      .finally(() => setLoading(false));
205	  }, []);
206	
207	  useEffect(() => { reload(); }, [reload]);
208	
209	  const handleAceitar = async (id) => {
210	    setProcessando(true);
211	    try {
212	      await aceitarSolicitacaoMotoboy(id);
213	      setFicha(null);
214	      setMsg({ tipo: 'ok', texto: 'Motoboy aceito!' });
215	      setTimeout(() => setMsg(null), 3000);
216	      reload();
217	    } catch (err) {
218	      setMsg({ tipo: 'erro', texto: err.message });
219	    } finally {
220	      setProcessando(false);
221	    }
222	  };
223	
224	  const handleRecusar = async (id, motivo) => {
225	    setProcessando(true);
226	    try {
227	      await recusarSolicitacaoMotoboy(id, motivo);
228	      setFicha(null);
229	      reload();
230	    } catch (err) {
231	      setMsg({ tipo: 'erro', texto: err.message });
232	    } finally {
233	      setProcessando(false);
234	    }
235	  };
236	
237	  const handleRevisar = async (id) => {
238	    setRevisando(id);
239	    try {
240	      await revisarSolicitacaoMotoboy(id);
241	      reload();
242	    } catch (err) {
243	      setMsg({ tipo: 'erro', texto: err.message });
244	    } finally {
245	      setRevisando(null);
246	    }
247	  };
248	
249	  const handleForcarLogout = async (mb) => {
250	    if (!window.confirm(`Encerrar a sessão de ${mb.name} no dispositivo onde está logado, pra liberar login em outro?`)) return;
251	    setForcandoLogout(mb.id);
252	    try {
253	      await forcarLogoutMotoboy(mb.id);
254	      setMotoboys((prev) => prev.map((m) => (m.id === mb.id ? { ...m, sessao_ativa: false } : m)));
255	    } catch (err) {
256	      setMsg({ tipo: 'erro', texto: err.message });
257	    } finally {
258	      setForcandoLogout(null);
259	    }
260	  };
261	
262	  const handleRemover = async (mb) => {
263	    if (!window.confirm(`Remover "${mb.name}" dos seus entregadores?`)) return;
264	    setRemovendo(mb.id);
265	    try {
266	      await removerAfiliacaoMotoboy(mb.id);
267	      setMotoboys((prev) => prev.filter((m) => m.id !== mb.id));
268	    } catch (err) {
269	      setMsg({ tipo: 'erro', texto: err.message });
270	    } finally {
271	      setRemovendo(null);
272	    }
273	  };
274	
275	  const handleSalvarForm = async (dados) => {
276	    setSalvandoForm(true);
277	    setErroForm(null);
278	    try {
279	      if (formModal === 'novo') {
280	        await criarMotoboy(dados);
281	        setMsg({ tipo: 'ok', texto: 'Motoboy cadastrado!' });
282	      } else {
283	        await editarMotoboy(formModal.id, dados);
284	        setMsg({ tipo: 'ok', texto: 'Motoboy atualizado!' });
