288	      reload();
289	    } catch (err) {
290	      setErroForm(err.message);
291	    } finally {
292	      setSalvandoForm(false);
293	    }
294	  };
295	
296	  const handleExcluir = async (mb) => {
297	    if (!window.confirm(`Excluir "${mb.name}" definitivamente? Essa ação não pode ser desfeita.`)) return;
298	    setExcluindo(mb.id);
299	    try {
300	      await excluirMotoboy(mb.id);
301	      setMotoboys((prev) => prev.filter((m) => m.id !== mb.id));
302	    } catch (err) {
303	      setMsg({ tipo: 'erro', texto: err.message });
304	    } finally {
305	      setExcluindo(null);
306	    }
307	  };
308	
309	  const handleBloquear = async (mb) => {
310	    setBloqueando(mb.id);
