314	    } catch (err) {
315	      setMsg({ tipo: 'erro', texto: err.message });
316	    } finally {
317	      setBloqueando(null);
318	    }
319	  };
320	
321	  if (loading) return (
322	    <div className="min-h-screen flex items-center justify-center bg-[#F4F4F5] dark:bg-[#18181B]">
323	      <div className="w-8 h-8 border-4 border-[#FF441F] border-t-transparent rounded-full animate-spin" />
324	    </div>
325	  );
326	
327	  return (
328	    <div className="min-h-screen bg-[#F4F4F5] dark:bg-[#18181B]">
329	      <RestauranteHeader active="/restaurante/motoboys" title="Motoboys" subtitle="Entregadores afiliados ao seu estabelecimento" onRefresh={reload} />
330	
331	      <main className="max-w-2xl mx-auto px-4 py-6 space-y-5">
332	        {msg && (
333	          <div className={`text-sm rounded-xl px-4 py-3 ${
334	            msg.tipo === 'ok' ? 'bg-green-50 dark:bg-green-950/40 text-green-700 dark:text-green-400 border border-green-200 dark:border-green-800' : 'bg-red-50 dark:bg-red-950/40 text-red-600 dark:text-red-400 border border-red-200 dark:border-red-800'
335	          }`}>
336	            {msg.texto}
337	          </div>
338	        )}
339	
340	        {/* Abas */}
341	        <div className="flex gap-1 bg-white dark:bg-[#27272A] border border-[#E4E4E7] dark:border-[#3F3F46] rounded-xl p-1">
342	          {[
343	            { id: 'pendentes', label: 'Pendentes', count: solicitacoes.length },
344	            { id: 'aceitas', label: 'Aceitas', count: motoboys.length },
345	            { id: 'recusadas', label: 'Recusadas', count: recusadas.length },
346	          ].map((t) => (
347	            <button key={t.id} onClick={() => setAba(t.id)}
348	              className={`flex-1 flex items-center justify-center gap-1.5 py-2 text-sm font-bold rounded-lg transition-colors ${
349	                aba === t.id ? 'bg-[#FF441F] text-white shadow-sm' : 'text-[#71717A] dark:text-[#A1A1AA] hover:bg-[#F4F4F5] dark:hover:bg-[#3F3F46]'
350	              }`}>
351	              {t.label}
352	              {t.count > 0 && (
353	                <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded-full ${
354	                  aba === t.id ? 'bg-white/20 text-white' : 'bg-[#F4F4F5] dark:bg-[#3F3F46] text-[#71717A] dark:text-[#A1A1AA]'
355	                }`}>
356	                  {t.count}
357	                </span>
358	              )}
359	            </button>
360	          ))}
361	        </div>
362	
363	        {aba === 'pendentes' && (
364	          <div className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] divide-y divide-[#F4F4F5] dark:divide-[#3F3F46]">
365	            {solicitacoes.length === 0 ? (
366	              <p className="p-5 text-sm text-[#71717A] dark:text-[#A1A1AA] text-center">Nenhuma solicitação pendente</p>
367	            ) : solicitacoes.map((s) => (
