370	                <div className="w-10 h-10 rounded-full overflow-hidden bg-[#F4F4F5] dark:bg-[#3F3F46] flex-shrink-0">
371	                  {s.motoboy.foto_perfil_url && !isPdfUrl(s.motoboy.foto_perfil_url)
372	                    ? <img src={s.motoboy.foto_perfil_url} alt={s.motoboy.name} className="w-full h-full object-cover" />
373	                    : <div className="w-full h-full flex items-center justify-center"><Icon name="User" size={16} className="text-[#A1A1AA]" /></div>}
374	                </div>
375	                <div className="flex-1 min-w-0">
376	                  <p className="text-sm font-semibold text-[#18181B] dark:text-[#F4F4F5] truncate">{s.motoboy.name}</p>
377	                  <p className="text-xs text-[#71717A] dark:text-[#A1A1AA]">{s.motoboy.phone}</p>
378	                </div>
379	                <Icon name="ChevronRight" size={16} className="text-[#A1A1AA] flex-shrink-0" />
380	              </button>
381	            ))}
382	          </div>
383	        )}
384	
385	        {aba === 'aceitas' && (
386	          <div className="space-y-3">
387	            <button onClick={() => { setErroForm(null); setFormModal('novo'); }}
388	              className="w-full flex items-center justify-center gap-1.5 py-2.5 border-2 border-dashed border-[#E4E4E7] dark:border-[#3F3F46] rounded-xl text-sm font-semibold text-[#71717A] dark:text-[#A1A1AA] hover:border-[#FF441F] hover:text-[#FF441F] transition-colors">
389	              <Icon name="Plus" size={16} /> Adicionar motoboy
390	            </button>
391	
392	            <div className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] divide-y divide-[#F4F4F5] dark:divide-[#3F3F46]">
393	              {motoboys.length === 0 ? (
394	                <p className="p-5 text-sm text-[#71717A] dark:text-[#A1A1AA] text-center">
395	                  Nenhum motoboy afiliado ainda. Cadastre o seu próprio acima, ou aguarde um entregador se cadastrar pelo app e solicitar atender aqui.
396	                </p>
397	              ) : motoboys.map((mb) => (
398	                <div key={mb.id} className="p-4 flex flex-wrap items-center gap-3">
399	                  <div className="w-9 h-9 rounded-full overflow-hidden bg-[#FF441F]/10 flex-shrink-0">
400	                    {mb.foto_perfil_url && !isPdfUrl(mb.foto_perfil_url)
401	                      ? <img src={mb.foto_perfil_url} alt={mb.name} className="w-full h-full object-cover" />
402	                      : <div className="w-full h-full flex items-center justify-center"><Icon name="Bike" size={16} className="text-[#FF441F]" /></div>}
403	                  </div>
404	                  <div className="flex-1 min-w-0">
405	                    <p className="text-sm font-semibold text-[#18181B] dark:text-[#F4F4F5] truncate">{mb.name}</p>
406	                    {mb.phone && <p className="text-xs text-[#71717A] dark:text-[#A1A1AA] truncate">{mb.phone}</p>}
407	                    <div className="flex flex-wrap gap-1 mt-1">
