410	                          Logado em 1 dispositivo
411	                        </span>
412	                      )}
413	                      {mb.bloqueado && (
414	                        <span className="inline-block text-[10px] px-2 py-0.5 rounded-full font-medium bg-red-100 dark:bg-red-950/40 text-red-700 dark:text-red-400">
415	                          Bloqueado
416	                        </span>
417	                      )}
418	                      {mb.gerenciado_por_mim && (
419	                        <span className="inline-block text-[10px] px-2 py-0.5 rounded-full font-medium bg-blue-100 dark:bg-blue-950/40 text-blue-700 dark:text-blue-400">
420	                          Cadastrado por você
421	                        </span>
422	                      )}
423	                    </div>
424	                  </div>
425	                  <div className="flex flex-wrap gap-2 flex-shrink-0">
426	                    {mb.gerenciado_por_mim && (
427	                      <button
428	                        onClick={() => { setErroForm(null); setFormModal(mb); }}
429	                        className="px-3 py-1.5 text-xs font-semibold rounded-lg bg-[#F4F4F5] dark:bg-[#3F3F46] text-[#27272A] dark:text-[#F4F4F5] hover:bg-[#E4E4E7] dark:hover:bg-[#3F3F46]"
430	                      >
431	                        Editar
432	                      </button>
433	                    )}
434	                    <button
435	                      onClick={() => handleBloquear(mb)}
436	                      disabled={bloqueando === mb.id}
437	                      className={`px-3 py-1.5 text-xs font-semibold rounded-lg disabled:opacity-50 ${
438	                        mb.bloqueado
439	                          ? 'bg-green-50 dark:bg-green-950/40 text-green-700 dark:text-green-400 hover:bg-green-100 dark:hover:bg-green-950/40'
440	                          : 'bg-amber-50 dark:bg-amber-950/40 text-amber-700 dark:text-amber-400 hover:bg-amber-100 dark:hover:bg-amber-950/40'
441	                      }`}
442	                    >
443	                      {bloqueando === mb.id ? '...' : mb.bloqueado ? 'Desbloquear' : 'Bloquear'}
444	                    </button>
445	                    {mb.sessao_ativa && (
446	                      <button
447	                        onClick={() => handleForcarLogout(mb)}
448	                        disabled={forcandoLogout === mb.id}
449	                        className="px-3 py-1.5 text-xs font-semibold rounded-lg bg-amber-50 dark:bg-amber-950/40 text-amber-700 dark:text-amber-400 hover:bg-amber-100 dark:hover:bg-amber-950/40 disabled:opacity-50"
450	                      >
451	                        {forcandoLogout === mb.id ? '...' : 'Forçar logout'}
452	                      </button>
453	                    )}
454	                    {mb.gerenciado_por_mim ? (
455	                      <button
456	                        onClick={() => handleExcluir(mb)}
457	                        disabled={excluindo === mb.id}
458	                        className="px-3 py-1.5 text-xs font-semibold rounded-lg bg-red-50 dark:bg-red-950/40 text-red-600 dark:text-red-400 hover:bg-red-100 dark:hover:bg-red-950/40 disabled:opacity-50"
459	                      >
460	                        {excluindo === mb.id ? '...' : 'Excluir'}
461	                      </button>
462	                    ) : (
463	                      <button
464	                        onClick={() => handleRemover(mb)}
465	                        disabled={removendo === mb.id}
466	                        className="px-3 py-1.5 text-xs font-semibold rounded-lg bg-red-50 dark:bg-red-950/40 text-red-600 dark:text-red-400 hover:bg-red-100 dark:hover:bg-red-950/40 disabled:opacity-50"
467	                      >
468	                        {removendo === mb.id ? '...' : 'Remover'}
469	                      </button>
470	                    )}
471	                  </div>
472	                </div>
473	              ))}
474	            </div>
475	          </div>
476	        )}
477	
478	        {aba === 'recusadas' && (
479	          <div className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] divide-y divide-[#F4F4F5] dark:divide-[#3F3F46]">
480	            {recusadas.length === 0 ? (
481	              <p className="p-5 text-sm text-[#71717A] dark:text-[#A1A1AA] text-center">Nenhuma solicitação recusada</p>
482	            ) : recusadas.map((s) => (
483	              <div key={s.id} className="p-4">
