494	                      onClick={() => { setFicha(s); setFichaSomenteLeitura(true); }}
495	                      className="px-3 py-1.5 text-xs font-semibold rounded-lg bg-[#F4F4F5] dark:bg-[#3F3F46] text-[#27272A] dark:text-[#F4F4F5] hover:bg-[#E4E4E7] dark:hover:bg-[#3F3F46]"
496	                    >
497	                      Ver ficha
498	                    </button>
499	                    <button
500	                      onClick={() => handleRevisar(s.id)}
501	                      disabled={revisando === s.id}
502	                      className="px-3 py-1.5 text-xs font-semibold rounded-lg bg-blue-50 dark:bg-blue-950/40 text-blue-600 dark:text-blue-400 hover:bg-blue-100 dark:hover:bg-blue-950/40 disabled:opacity-50"
503	                    >
504	                      {revisando === s.id ? '...' : 'Revisão'}
