510	                )}
511	              </div>
512	            ))}
513	          </div>
514	        )}
515	      </main>
516	
517	      {ficha && (
518	        <FichaModal
519	          solicitacao={ficha}
520	          onFechar={() => { setFicha(null); setFichaSomenteLeitura(false); }}
